<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> env.action_space.sample()</span></span>
